const startX = -3.35;
const topY = 2.3;
const dx = 0.42;
const dy = 0.55;
const pegs = [];
for (let row = 0; row < 6; row++) {
  for (let j = 0; j <= row; j++) {
    const peg = new Circle({ radius: 0.075, color: GRAY });
    peg.setFill(GRAY, 1);
    peg.moveTo([startX + (2 * j - row) * dx, topY - row * dy, 0]);
    pegs.push(peg);
  }
}
scene.add(...pegs);

const boardLabel = new Text({ text: '6 left/right choices', color: BLUE_B, fontSize: 20 });
boardLabel.moveTo([-3.35, -1.45, 0]);
