const railR = new Polygon({ vertices: [[-0.7, -1.25, 0], [-0.7, 2.65, 0]], color: BLUE_D });
railL.setStrokeWidth(2);
railR.setStrokeWidth(2);
scene.add(railL, railR);

const histBase = new Polygon({ vertices: [[0.7, -2.55, 0], [6.25, -2.55, 0]], color: WHITE });
histBase.setStrokeWidth(2);
scene.add(histBase);

const chartTitle = new Text({ text: 'Where balls land', color: WHITE, fontSize: 22 });
chartTitle.moveTo([3.45, 2.35, 0]);
scene.add(chartTitle);

const counts = [1, 4, 7, 8, 7, 4, 1];
const bars = [];
for (let k = 0; k <= 6; k++) {
  const h = counts[k] * 0.32;
  const bar = new Rectangle({ width: 0.48, height: h, color: BLUE_C });
  bar.setFill(BLUE_C, 0.7);
  bar.moveTo([1.15 + k * 0.78, -2.55 + h / 2, 0]);
  bars.push(bar);
  const tick = new Text({ text: String(k), color: GRAY, fontSize: 16 });
  tick.moveTo([1.15 + k * 0.78, -2.9, 0]);
  scene.add(tick);
  makeHoverable(bar, scene, { hoverScale: 1.08, hoverColor: YELLOW });
}

const xLabel = new Text({ text: 'number of right turns', color: GRAY, fontSize: 16 });
xLabel.moveTo([3.45, -3.35, 0]);
scene.add(xLabel);

