  bars.forEach((bar, i) => bar.setColor(i === 3 ? YELLOW : BLUE_C));
}});
controls.addButton({ label: 'Reset colors', onClick: () => {
  bars.forEach(bar => bar.setColor(BLUE_C));
}});

